#!/usr/bin/env node
// The JSON files in data/ are the source of truth. Browsers block fetch() over file://, so this script
// copies them verbatim into data/data.js (window.PW_DATA). Run after editing any JSON:  node tools/bundle-data.js
const fs = require('fs'), path = require('path'), loadData = require('./load-data.js');
const d = loadData();
const out = '/* GENERATED by tools/bundle-data.js from data/*.json — do not edit by hand. */\nwindow.PW_DATA = ' + JSON.stringify(d) + ';\n';
fs.writeFileSync(path.join(__dirname, '..', 'data', 'data.js'), out);
console.log('wrote data/data.js (' + out.length + ' bytes) from ' + loadData.FILES.map(f => f + '.json').join(', '));

// Frozen v0.1 data for the legacy replay player (A006), loaded on demand by the browser only when a v0.1 file is imported.
const legacyDir = path.join(__dirname, '..', 'data', 'legacy', 'v0.1');
if (fs.existsSync(legacyDir)) {
  const ld = loadData(legacyDir);
  const lout = '/* GENERATED by tools/bundle-data.js from data/legacy/v0.1/*.json — frozen v0.1 rules, do not edit. */\nwindow.PW_LEGACY_DATA = ' + JSON.stringify(ld) + ';\n';
  fs.writeFileSync(path.join(__dirname, '..', 'data', 'legacy-data.js'), lout);
  console.log('wrote data/legacy-data.js (' + lout.length + ' bytes)');
}
